   379  int get_header_info(blosc2_frame *frame, int32_t *header_len, int64_t *frame_len, int64_t *nbytes,
   380                      int64_t *cbytes, int32_t *chunksize, int32_t *nchunks, int32_t *typesize,
   381                      uint8_t *compcode, uint8_t *clevel, uint8_t *filters, uint8_t *filters_meta) {
   382    uint8_t* framep = frame->sdata;
   383    uint8_t header[FRAME_HEADER_MINLEN];
   384
   385    if (frame->len <= 0) {
   386      return -1;
   387    }
   388
   389    if (frame->sdata == NULL) {
   390      size_t rbytes = 0;
   391      FILE* fp = fopen(frame->fname, "rb");
   392      if (fp != NULL) {
   393        rbytes = fread(header, 1, FRAME_HEADER_MINLEN, fp);
   394        fclose(fp);
   395      }
   396      (void) rbytes;
   397      if (rbytes != FRAME_HEADER_MINLEN) {
   398        return -1;
   399      }
   400      framep = header;
   401    }
   402
   403    // Fetch some internal lengths
   404    swap_store(header_len, framep + FRAME_HEADER_LEN, sizeof(*header_len));
   405    swap_store(frame_len, framep + FRAME_LEN, sizeof(*frame_len));
   406    swap_store(nbytes, framep + FRAME_NBYTES, sizeof(*nbytes));
   407    swap_store(cbytes, framep + FRAME_CBYTES, sizeof(*cbytes));
   408    swap_store(chunksize, framep + FRAME_CHUNKSIZE, sizeof(*chunksize));
   409    if (typesize != NULL) {
   410      swap_store(typesize, framep + FRAME_TYPESIZE, sizeof(*typesize));
   411    }
   412
   413    // Codecs
   414    uint8_t frame_codecs = framep[FRAME_CODECS];
   415    if (clevel != NULL) {
   416      *clevel = frame_codecs >> 4u;
   417    }
   418    if (compcode != NULL) {
   419      *compcode = frame_codecs & 0xFu;
   420    }
   421
   422    // Filters
   423    if (filters != NULL && filters_meta != NULL) {
   424      uint8_t nfilters = framep[FRAME_FILTER_PIPELINE];
   425      if (nfilters > BLOSC2_MAX_FILTERS) {
   426        fprintf(stderr, "Error: the number of filters in frame header are too large for Blosc2");
   427        return -1;
   428      }
   429      uint8_t *filters_ = framep + FRAME_FILTER_PIPELINE + 1;
   430      uint8_t *filters_meta_ = framep + FRAME_FILTER_PIPELINE + 1 + FRAME_FILTER_PIPELINE_MAX;
   431      for (int i = 0; i < nfilters; i++) {
   432        filters[i] = filters_[i];
   433        filters_meta[i] = filters_meta_[i];
   434      }
   435    }
   436
   437    if (*nbytes > 0 && *chunksize > 0) {
   438      // We can compute the number of chunks only when the frame has actual data
   439      *nchunks = (int32_t) (*nbytes / *chunksize);
   440      if (*nbytes % *chunksize > 0) {
   441        *nchunks += 1;
   442      }
   443    } else {
   444      *nchunks = 0;
   445    }
   446
   447    return 0;
   448  }
